UPDATE PEACH_SCHEDULER_JOB
SET STATE = #{toState},
    SCHEDULE_VERSION = SCHEDULE_VERSION + 1,
    SYNC_STATUS = 'PENDING',
    VERSION = VERSION + 1,
    MODIFIER_ID = #{modifierId},
    MODIFY_TIME = NOW(3)
WHERE ID = #{id}
  AND STATE = #{fromState}
  AND VERSION = #{version}

UPDATE PEACH_SCHEDULER_JOB
SET SYNC_STATUS = 'SYNCED', LAST_SYNC_ERROR = NULL
WHERE ID = #{id} AND SCHEDULE_VERSION = #{scheduleVersion}

UPDATE PEACH_SCHEDULER_JOB
SET SYNC_STATUS = 'FAILED', LAST_SYNC_ERROR = #{error}
WHERE ID = #{id} AND SCHEDULE_VERSION = #{scheduleVersion}

mapper.select:
SELECT 
FROM PEACH_SCHEDULER_JOB
WHERE STATE <> 'DELETED'

    AND APPLICATION_NAME = #{applicationName}


    AND STATE = #{state}


    AND (JOB_CODE LIKE CONCAT('%', #{keyword}, '%') OR JOB_NAME LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY MODIFY_TIME DESC
LIMIT #{safePageSize} OFFSET #{offset}
